CREATE TABLE principal_roles (principal_id TEXT PRIMARY KEY REFERENCES principals(id), kind TEXT NOT NULL CHECK(kind IN ('agent','user')));
CREATE TABLE tasks (id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES rooms(id), creator_id TEXT NOT NULL REFERENCES principals(id), owner_id TEXT REFERENCES principals(id), spec_json TEXT NOT NULL CHECK(json_valid(spec_json)), state TEXT NOT NULL CHECK(state IN ('open','in_progress','blocked','review','done','canceled')), version INTEGER NOT NULL CHECK(version>=1), current_submission_id TEXT REFERENCES task_submissions(id), cancel_reason TEXT, created_at_ms INTEGER NOT NULL, updated_at_ms INTEGER NOT NULL);
CREATE INDEX tasks_room ON tasks(room_id,id);
CREATE TABLE task_leases (task_id TEXT PRIMARY KEY REFERENCES tasks(id), holder_id TEXT REFERENCES principals(id), lease_epoch INTEGER NOT NULL CHECK(lease_epoch>=0), expires_at_ms INTEGER NOT NULL CHECK(expires_at_ms>=0));
CREATE TABLE task_submissions (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), actor_id TEXT NOT NULL REFERENCES principals(id), lease_epoch INTEGER NOT NULL, artifact_message_id TEXT NOT NULL REFERENCES messages(id), artifact_revision INTEGER NOT NULL CHECK(artifact_revision>=1), disposition TEXT NOT NULL CHECK(disposition IN ('review','blocked')), reason TEXT, submitted_at_ms INTEGER NOT NULL);
CREATE TABLE task_audit (id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id), room_id TEXT NOT NULL REFERENCES rooms(id), operation TEXT NOT NULL, target_id TEXT NOT NULL, version INTEGER, created_at TEXT NOT NULL);
CREATE TRIGGER task_spec_immutable BEFORE UPDATE ON tasks WHEN NEW.id!=OLD.id OR NEW.room_id!=OLD.room_id OR NEW.creator_id!=OLD.creator_id OR NEW.owner_id IS NOT OLD.owner_id OR NEW.spec_json!=OLD.spec_json OR NEW.created_at_ms!=OLD.created_at_ms BEGIN SELECT RAISE(ABORT,'immutable task spec'); END;
CREATE TRIGGER task_version BEFORE UPDATE ON tasks WHEN NEW.version!=OLD.version+1 OR OLD.state IN ('done','canceled') BEGIN SELECT RAISE(ABORT,'invalid task version or terminal state'); END;
CREATE TRIGGER task_submission_valid BEFORE INSERT ON task_submissions WHEN NOT EXISTS (SELECT 1 FROM tasks t JOIN message_history h ON h.message_id=NEW.artifact_message_id AND h.version=NEW.artifact_revision WHERE t.id=NEW.task_id AND t.room_id=h.room_id AND h.actor_id=NEW.actor_id) BEGIN SELECT RAISE(ABORT,'invalid task artifact'); END;
CREATE TRIGGER task_current_valid BEFORE UPDATE ON tasks WHEN NEW.current_submission_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM task_submissions s WHERE s.id=NEW.current_submission_id AND s.task_id=NEW.id AND s.disposition='review') BEGIN SELECT RAISE(ABORT,'invalid current submission'); END;
CREATE TRIGGER tasks_no_delete BEFORE DELETE ON tasks BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER submissions_no_update BEFORE UPDATE ON task_submissions BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER submissions_no_delete BEFORE DELETE ON task_submissions BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER task_audit_no_update BEFORE UPDATE ON task_audit BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER task_audit_no_delete BEFORE DELETE ON task_audit BEGIN SELECT RAISE(ABORT,'immutable'); END;
